			"concepts": [
				{
					"id": "direct-cli",
					"title": "Command model",
					"body": [
						"DSP automation uses hise-cli dsp <command> [flags].",
						"Commands use explicit flags for network host modules, nodes, source endpoints, target parameters, and values.",
						"Use --agent for compact JSON and stable error codes."
					]
				},
				{
					"id": "network-host",
					"title": "Network host module",
					"body": [
						"--module is the HISE processor/module context that owns the DSP network.",
						"Builder mode creates or loads the network on that host with builder set --module <module> --network <name>.",
						"DSP commands edit the existing network on that host."
					]
				},
				{
					"id": "node-parameters",
					"title": "Node parameters",
					"body": [
						"--node identifies the scriptnode node to inspect or edit.",
						"--param identifies a target parameter on that node.",
						"--value is coerced according to HISE parameter metadata where available.",
						"Dynamic parameter flags may be used for simple node parameter writes; use --param/--value when names collide with reserved flags."
					]
				},
				{
					"id": "connections",
					"title": "Connection model",
					"body": [
						"dsp connect uses --source, --target, and --param like ui connect.",
						"--source is a DSP node unless qualified by --source-param or --source-output.",
						"--target is the destination DSP node.",
						"--param is the destination parameter.",
						"--matched copies compatible range or metadata where HISE exposes enough information.",
						"Scaled DSP connections map the source range through the target parameter range.",
						"To invert a scaled connection, reverse the target parameter range, for example set --range \"1,0\" on a 0..1 target; this maps source 0.1 to target 0.9.",
						"Target-range inversion works whether the range is changed before or after connecting.",
						"--source-param and --source-output are mutually exclusive."
					]
				},
				{
					"id": "dry-run-validation",
					"title": "Dry-run validation",
					"body": [
						"DSP --dry-run executes the requested mutation inside a temporary HISE undo plan and always discards that plan.",
						"This validates against HISE's actual constraints without leaving project state changed."
					]
				},
				{
					"id": "trace-validation",
					"title": "Trace validation",
					"body": [
						"dsp trace combines a temporary runtime stimulus with signal and parameter probes.",
						"Use --inject for signal stimuli and --inject-param for temporary parameter values.",
						"Use --probe-recursive for recursive signal tracing; it includes the topology tree automatically.",
						"Use --probe-changed-parameters to report changed runtime parameters and touched edges.",
						"Use repeated --probe-param flags when suspected parameter targets are known.",
						"--trace-compact changes the trace payload shape; global --compact only compacts the CLI output envelope."
					]
				},
				{
					"id": "runtime-status",
					"title": "Runtime status",
					"body": [
						"dsp status is a cheap graph-level runtime validity check for the active network after loading, editing, recompiling, or changing network properties.",
						"It can catch wrong MIDI or processing context, compilation flag incompatibilities, mono/polyphony mismatch, processing spec mismatches, invalid parent or container setup, clone container mismatch, dynamic routing errors, missing assets or third-party node resources, SNEX/expression compile failures, and deprecated scriptnode nodes.",
						"Runtime scriptnode errors are returned as endpoint status with ok=false; request validation, missing modules, and missing networks remain normal HISE API errors.",
						"After fixing a reported exception, call /api/script/recompile for the DSP module ID when a forced reinitialisation is needed."
					]
				}
			],
